	/** Get the remaining lifespan of this actor. If zero is returned the actor lives forever. */
	UFUNCTION(BlueprintCallable, Category="Actor", meta=(Keywords = "delete destroy"))
	ENGINE_API virtual float GetLifeSpan() const;

