	UFUNCTION(BlueprintCallable, Category = RayTracing)
	ENGINE_API void SetRayTracingGroupId(int32 InRaytracingGroupId);

	/** Return the RayTracingGroupId for this actor. */
	UFUNCTION(BlueprintCallable, Category = RayTracing)
	ENGINE_API int32 GetRayTracingGroupId() const;

