#if WITH_EDITORONLY_DATA
	/** The UHLODLayer in which this actor should be included. */
	UPROPERTY(EditAnywhere, Category = HLOD, meta = (DisplayName = "HLOD Layer"))
	TObjectPtr<class UHLODLayer> HLODLayer;
